# Models with a `public_id` (UUID, generated by Postgres) expose it instead of
# the internal integer id: URL helpers use it via to_param, and controllers
# look records up with find_public!. Models without the column are unaffected.
#
# Adding it to a new model is one migration line:
#   t.uuid :public_id, null: false, default: -> { "gen_random_uuid()" }, index: { unique: true }
module PublicId
  extend ActiveSupport::Concern

  def to_param
    has_attribute?(:public_id) ? public_id : super
  end

  # dom_id(record) and form ids use to_key, so HTML element ids carry the public ID too
  def to_key
    has_attribute?(:public_id) && public_id ? [public_id] : super
  end

  class_methods do
    # Works on relations too: Current.account.leads.find_public!(params[:id])
    def find_public!(public_id)
      find_by!(public_id: public_id.to_s)
    end
  end
end
